# tools/generated/damage.txt (tools/nsss/DumpDamage) -> source/game/EntityDamage.h
import os
here = os.path.dirname(os.path.abspath(__file__))
rows = [l.split() for l in open(os.path.join(here, 'generated/damage.txt')) if l.strip()]
o = ['#pragma once',
     '// Generated by tools/gen_damage.py from the NSSS jar (tools/nsss/DumpDamage). Do not edit.',
     '#include <cstdint>', '', 'namespace survival {',
     '// Item.getDamageVsEntity (InventoryPlayer.getDamageVsEntity): 1 for a fist or anything not listed',
     'inline int entityDamage(int id) {', '    switch (id) {']
o += ['    case %s: return %s; // %s' % (r[0], r[1], r[4]) for r in rows if r[1] != '1']
o += ['    default: return 1;', '    }', '}',
      '// damageItemHit: how much hitting a mob wears the item (ItemSword 1, ItemTool 2; 0: it doesn\'t)',
      'inline int hitWear(int id) {', '    switch (id) {']
o += ['    case %s: return %s;' % (r[0], r[2]) for r in rows if r[2] != '0']
o += ['    default: return 0;', '    }', '}',
      '// damageItemMine: how much breaking a block wears it (ItemSword 2, ItemTool 1)',
      'inline int mineWear(int id) {', '    switch (id) {']
o += ['    case %s: return %s;' % (r[0], r[3]) for r in rows if r[3] != '0']
o += ['    default: return 0;', '    }', '}', '} // namespace survival', '']
open(os.path.join(here, '../source/game/EntityDamage.h'), 'w').write('\n'.join(o))
